<script setup lang="ts">
const { public: { theme } } = useRuntimeConfig()
const mode = useThemeMode()

useHead({
  htmlAttrs: {
    lang: 'en',
    'data-theme': computed(() => (mode.value === 'system' ? undefined : mode.value)),
  },
  title: 'SCMP Internal Operations AI Assistant',
  style: [{ id: 'theme-vars', innerHTML: buildThemeCss(theme) }],
})
</script>

<template>
  <NuxtRouteAnnouncer />
  <NuxtLayout>
    <NuxtPage />
  </NuxtLayout>
</template>
export default defineNuxtRouteMiddleware(async (to) => {
  const { user, notice, checked, fetchMe } = useAuth()

  // First render (SSR) validates the httpOnly session cookie via /me; the result travels to the browser
  // in the payload, so hydration and later navigations do not repeat the call.
  if (!checked.value) await fetchMe()

  // Role rules live in utils/access.ts: `/` needs can_request, `/approvals*` needs approves, `/login` bounces
  // signed-in users to their home, and a user with neither capability is sent to /no-access.
  const target = routeRedirect(user.value, to.path)
  if (!target) return
  if (target === '/login' && !user.value) {
    // An SSR redirect starts a new request, so carry the "expired" reason in a harmless query flag.
    return navigateTo(notice.value ? { path: '/login', query: { reason: 'expired' } } : '/login')
  }
  return navigateTo(target)
})
/** Role-aware access and navigation rules (pure; unit-tested in tests/access.test.ts). */
import type { ApprovalScope, AuthUser } from './auth'

type Capabilities = Pick<AuthUser, 'can_request' | 'approves'>

export const NO_ACCESS_PATH = '/no-access'

/** Where a signed-in user lands: the chat when they may file requests, else their approvals queue, else "no access". */
export function homePath(user: Capabilities | null | undefined): string {
  if (!user) return '/login'
  if (user.can_request) return '/'
  if (user.approves) return '/approvals'
  return NO_ACCESS_PATH
}

export function hasAnyAccess(user: Capabilities | null | undefined): boolean {
  return !!user && (user.can_request || user.approves !== null)
}

/**
 * Route rule for the global middleware. Returns the path to redirect to, or null when the route is allowed.
 * `/` needs can_request; `/approvals*` needs approves; `/no-access` is only for users who have nothing else.
 */
export function routeRedirect(user: Capabilities | null | undefined, path: string): string | null {
  const clean = path.split(/[?#]/)[0] || '/'
  if (clean === '/login') return user ? homePath(user) : null
  if (!user) return '/login'
  if (clean === '/') return user.can_request ? null : homePath(user)
  if (clean === '/approvals' || clean.startsWith('/approvals/')) return user.approves ? null : homePath(user)
  if (clean === NO_ACCESS_PATH) return hasAnyAccess(user) ? homePath(user) : null
  return null
}

export interface NavTab {
  key: 'requests' | 'approvals'
  label: string
  to: string
}

/** Header tabs the user may use, in a fixed order. */
export function navTabs(user: Capabilities | null | undefined): NavTab[] {
  const tabs: NavTab[] = []
  if (user?.can_request) tabs.push({ key: 'requests', label: 'My requests', to: '/' })
  if (user?.approves) tabs.push({ key: 'approvals', label: 'Approvals', to: '/approvals' })
  return tabs
}

/** True when the tab is the current section (`/` is only current on exactly `/`). */
export function isTabActive(tab: NavTab, path: string): boolean {
  return tab.to === '/' ? path === '/' : path === tab.to || path.startsWith(`${tab.to}/`)
}

export function approvalsHeading(approves: ApprovalScope | null | undefined): string {
  if (approves === 'leave') return 'Leave approvals'
  if (approves === 'claim') return 'Claim approvals'
  return 'Approvals'
}
import type { NitroFetchOptions, NitroFetchRequest } from 'nitropack'

/**
 * `$fetch` wrapper for authenticated API calls: sends the httpOnly session cookie (`credentials: 'include'`,
 * or the forwarded cookie header during SSR), adds the CSRF header on unsafe methods, and signs the user out
 * (clearing state and redirecting to /login) when the API answers 401.
 */
export function useApi() {
  const { request, clearSession, withContext, expiredNotice } = useAuth()

  return async function api<T>(path: string, options: NitroFetchOptions<NitroFetchRequest> = {}): Promise<T> {
    try {
      return await request<T>(path, options)
    }
    catch (error) {
      if (extractStatus(error) === 401) {
        clearSession(expiredNotice)
        await withContext(() => navigateTo('/login'))
      }
      throw error
    }
  }
}
import type { AppNotification } from '~/types/notifications'

/**
 * Shared notification state for the bell (kept in `useState`, cleared on sign-in / sign-out). Reads and writes go
 * through `useApi`. Marking as read is optimistic and rolls back when the API refuses. A poll that started before a
 * local change is discarded, so an old response never brings back a dot the user just cleared.
 */
export function useNotifications() {
  const api = useApi()
  const items = useState<AppNotification[]>('notif-items', () => [])
  const unread = useState<number>('notif-unread', () => 0)
  const loaded = useState<boolean>('notif-loaded', () => false)
  const error = useState<string | null>('notif-error', () => null)
  const actionError = ref<string | null>(null)
  const loading = ref(false)
  let mutations = 0

  async function refresh() {
    const startedAt = mutations
    loading.value = true
    try {
      const data = parseNotificationList(await api<unknown>(`/api/notifications?limit=${NOTIFICATION_LIMIT}`))
      if (startedAt !== mutations) return
      items.value = data.items
      unread.value = data.unread_count
      error.value = null
      loaded.value = true
    }
    catch {
      // A failed background poll keeps what is shown; only a list that never loaded reports an error.
      if (!loaded.value) error.value = 'Notifications could not be loaded.'
    }
    finally {
      loading.value = false
    }
  }

  async function markRead(id: number) {
    const update = applyRead(items.value, unread.value, id, new Date().toISOString())
    if (!update.changed) return
    const snapshot = { items: items.value, unread: unread.value }
    mutations++
    items.value = update.items
    unread.value = update.unread
    try {
      await api(`/api/notifications/${id}/read`, { method: 'POST' })
    }
    catch {
      mutations++
      items.value = snapshot.items
      unread.value = snapshot.unread
      actionError.value = 'Could not mark that notification as read. Please try again.'
    }
  }

  async function markAllRead() {
    const update = applyReadAll(items.value, new Date().toISOString())
    if (!update.changed && unread.value === 0) return
    const snapshot = { items: items.value, unread: unread.value }
    mutations++
    items.value = update.items
    unread.value = update.unread
    try {
      await api('/api/notifications/read-all', { method: 'POST' })
    }
    catch {
      mutations++
      items.value = snapshot.items
      unread.value = snapshot.unread
      actionError.value = 'Could not mark all as read. Please try again.'
    }
  }

  return { items, unread, loaded, loading, error, actionError, refresh, markRead, markAllRead }
}
/**
 * Runs `task` every 30 s while the tab is visible, and again when the tab becomes visible or the window regains
 * focus (never twice within a few seconds, never while a run is still in flight). Call it in `setup`; timers and
 * listeners are removed on unmount. `task` must catch its own errors.
 */
export function usePolling(task: () => Promise<unknown>, options: { intervalMs?: number, immediate?: boolean } = {}) {
  const intervalMs = options.intervalMs ?? POLL_INTERVAL_MS
  let timer: ReturnType<typeof setInterval> | undefined
  let inFlight = false
  let lastRunAt: number | null = null

  async function run() {
    inFlight = true
    lastRunAt = Date.now()
    try {
      await task()
    }
    finally {
      inFlight = false
    }
  }

  function onTick() {
    if (shouldTick({ hidden: document.hidden, inFlight })) void run()
  }

  function onFocusOrVisible() {
    if (shouldRefreshOnFocus({ hidden: document.hidden, inFlight, lastRunAt, now: Date.now() })) void run()
  }

  onMounted(() => {
    if (options.immediate !== false) void run()
    timer = setInterval(onTick, intervalMs)
    document.addEventListener('visibilitychange', onFocusOrVisible)
    window.addEventListener('focus', onFocusOrVisible)
  })

  onBeforeUnmount(() => {
    if (timer) clearInterval(timer)
    document.removeEventListener('visibilitychange', onFocusOrVisible)
    window.removeEventListener('focus', onFocusOrVisible)
  })

  return { refresh: run }
}
import type { ApprovalList, ApprovalListItem } from '~/types/approvals'

/**
 * The signed-in approver's pending queue (`GET /api/approvals`), shared by the header badge and the list page.
 * A background refresh (the 30 s poll) keeps what is on screen when it fails; a foreground load reports errors.
 */
export function useApprovalQueue() {
  const api = useApi()
  const items = useState<ApprovalListItem[]>('approvals-items', () => [])
  const loaded = useState<boolean>('approvals-loaded', () => false)
  const error = useState<string | null>('approvals-error', () => null)
  /** One-shot message from the detail page ("You approved leave request #12 ...", or the 409 explanation). */
  const flash = useState<{ tone: 'green' | 'amber', text: string } | null>('approvals-flash', () => null)
  const loading = ref(false)
  const count = computed(() => items.value.length)

  async function refresh(options: { background?: boolean } = {}) {
    loading.value = true
    if (!options.background) error.value = null
    try {
      const data = await api<Partial<ApprovalList>>('/api/approvals')
      items.value = Array.isArray(data.items) ? data.items : []
      loaded.value = true
      error.value = null
    }
    catch (cause) {
      if (!options.background || !loaded.value) error.value = approvalErrorMessage(extractStatus(cause), 'list')
    }
    finally {
      loading.value = false
    }
  }

  return { items, count, loaded, loading, error, flash, refresh }
}
/** Pure notification helpers (tests/notifications.test.ts). Titles and bodies are always rendered as text. */
import type { AppNotification, NotificationList } from '../types/notifications'

export const NOTIFICATION_LIMIT = 20

export function isUnread(n: Pick<AppNotification, 'read_at'>): boolean {
  return !n.read_at
}

/** Badge text: nothing for 0, the number up to 99, then "99+". */
export function formatBadgeCount(count: number): string {
  if (!Number.isFinite(count) || count <= 0) return ''
  return count > 99 ? '99+' : String(Math.floor(count))
}

/** Accessible name of the bell button, including the count. */
export function bellLabel(count: number): string {
  if (!Number.isFinite(count) || count <= 0) return 'Notifications, none unread'
  const shown = count > 99 ? 'more than 99' : String(Math.floor(count))
  return `Notifications, ${shown} unread`
}

/** Text for the polite live region when the count changes. */
export function unreadAnnouncement(count: number): string {
  if (!Number.isFinite(count) || count <= 0) return 'No unread notifications'
  return count === 1 ? '1 unread notification' : `${count > 99 ? 'More than 99' : count} unread notifications`
}

/** Only in-app paths are followed (no protocol-relative or absolute URLs from the API). */
export function safeInternalLink(link: string | null | undefined): string | null {
  if (typeof link !== 'string') return null
  const value = link.trim()
  return value.startsWith('/') && !value.startsWith('//') && !value.includes('\\') ? value : null
}

export type NotificationTarget = { kind: 'link', to: string } | { kind: 'dialog' }

/** Approvers follow the link; requesters (no link) get the detail dialog. */
export function notificationTarget(n: Pick<AppNotification, 'link'>): NotificationTarget {
  const to = safeInternalLink(n.link)
  return to ? { kind: 'link', to } : { kind: 'dialog' }
}

export interface ReadUpdate {
  items: AppNotification[]
  unread: number
  /** False when the notification was missing or already read (no request is needed). */
  changed: boolean
}

/** Optimistic "mark one as read"; the count drops by one only when the item really was unread. */
export function applyRead(items: readonly AppNotification[], unread: number, id: number, now: string): ReadUpdate {
  const target = items.find(n => n.id === id)
  if (!target || !isUnread(target)) return { items: [...items], unread, changed: false }
  return {
    items: items.map(n => (n.id === id ? { ...n, read_at: now } : n)),
    unread: Math.max(0, unread - 1),
    changed: true,
  }
}

/** Optimistic "mark all as read". The unread count becomes 0. */
export function applyReadAll(items: readonly AppNotification[], now: string): ReadUpdate {
  const changed = items.some(isUnread)
  return { items: items.map(n => (isUnread(n) ? { ...n, read_at: now } : n)), unread: 0, changed }
}

function toNotification(value: unknown): AppNotification | null {
  if (typeof value !== 'object' || value === null) return null
  const v = value as Record<string, unknown>
  if (typeof v.id !== 'number' || typeof v.title !== 'string') return null
  return {
    id: v.id,
    event_type: typeof v.event_type === 'string' ? v.event_type : '',
    title: v.title,
    body: typeof v.body === 'string' ? v.body : '',
    request_type: v.request_type === 'leave' || v.request_type === 'claim' ? v.request_type : null,
    request_id: typeof v.request_id === 'number' ? v.request_id : null,
    read_at: typeof v.read_at === 'string' ? v.read_at : null,
    created_at: typeof v.created_at === 'string' ? v.created_at : '',
    link: typeof v.link === 'string' ? v.link : null,
  }
}

/** Tolerant parse of GET /api/notifications: malformed rows are dropped, the count falls back to the unread rows. */
export function parseNotificationList(payload: unknown): NotificationList {
  const v = (typeof payload === 'object' && payload !== null ? payload : {}) as Record<string, unknown>
  const items = (Array.isArray(v.items) ? v.items : []).map(toNotification).filter((n): n is AppNotification => n !== null)
  const unread = typeof v.unread_count === 'number' && v.unread_count >= 0 ? v.unread_count : items.filter(isUnread).length
  return { items, unread_count: unread }
}
/** Types for the Phase 3 notification API (see docs/phase3-approval-design.md, section 4 and 5). */
import type { RequestType } from './chat'

export interface AppNotification {
  id: number
  event_type: string
  /** Plain text: always render as text, never as HTML. */
  title: string
  body: string
  request_type: RequestType | null
  request_id: number | null
  read_at: string | null
  created_at: string
  /** Set for approvers (navigate); null for requesters (open the detail dialog). */
  link: string | null
}

export interface NotificationList {
  items: AppNotification[]
  unread_count: number
}
/** Polling rules shared by the bell and the approvals list (pure; tests/notifications.test.ts). */

export const POLL_INTERVAL_MS = 30_000
/** Focus and visibility events fire together; ignore a second refresh inside this window. */
export const POLL_MIN_GAP_MS = 5_000

export interface PollState {
  hidden: boolean
  inFlight: boolean
  lastRunAt: number | null
  now: number
}

/** The 30 s timer: skip while the tab is hidden or a refresh is already running. */
export function shouldTick(state: Pick<PollState, 'hidden' | 'inFlight'>): boolean {
  return !state.hidden && !state.inFlight
}

/** Focus / visibility return: refresh at once unless one just ran or is running. */
export function shouldRefreshOnFocus(state: PollState, minGapMs: number = POLL_MIN_GAP_MS): boolean {
  if (state.hidden || state.inFlight) return false
  return state.lastRunAt === null || state.now - state.lastRunAt >= minGapMs
}
<script setup lang="ts">
useHead({ title: 'My requests - SCMP Internal Operations AI Assistant' })
</script>

<!-- The global middleware only lets users with can_request reach this route. -->
<template>
  <main class="h-full">
    <ChatWorkspace />
  </main>
</template>

/** Pure, framework-free chat helpers (unit-tested offline in tests/chat.test.ts). */
import type {
  AttachmentInfo,
  CardAction,
  CardField,
  CardState,
  ConfirmationCardData,
  ConversationSummary,
  Message,
  RequestStatus,
  ResultOutcome,
  TurnResponse,
  WarningCode,
} from '../types/chat'

export const MAX_MESSAGE_LENGTH = 1000

/** Suggestion chips of the empty state; picking one sends it as a message. */
export const CHAT_SUGGESTIONS: readonly string[] = [
  'I need annual leave next Monday and Tuesday',
  'Half day sick leave tomorrow afternoon',
  'Claim HKD 180 for a taxi yesterday',
  'What is the status of my requests?',
]

/* ---- Status badges: colour is never the only cue (each tone has an icon and a text label) ---- */

export type Tone = 'amber' | 'green' | 'red' | 'grey'
export type IconName = 'clock' | 'check' | 'x' | 'alert' | 'ban' | 'pencil'

export interface StatusMeta {
  label: string
  tone: Tone
  icon: IconName
}

const STATUS_META: Readonly<Record<RequestStatus, StatusMeta>> = {
  draft: { label: 'Draft', tone: 'grey', icon: 'pencil' },
  pending_approval: { label: 'Pending approval', tone: 'amber', icon: 'clock' },
  submission_failed: { label: 'Submission failed', tone: 'red', icon: 'alert' },
  approved: { label: 'Approved', tone: 'green', icon: 'check' },
  rejected: { label: 'Rejected', tone: 'red', icon: 'x' },
  cancelled: { label: 'Cancelled', tone: 'grey', icon: 'ban' },
}

/** Label, tone and icon for a request status; unknown statuses fall back to a neutral badge. */
export function statusMeta(status: string, fallbackLabel?: string): StatusMeta {
  const known = (STATUS_META as Record<string, StatusMeta | undefined>)[status]
  if (known) return known
  return { label: fallbackLabel || 'Unknown status', tone: 'grey', icon: 'clock' }
}

/** CSS class for a tone (palette defined in main.css, contrast >= 4.5:1 in both themes). */
export function toneClass(tone: Tone): string {
  return `tone tone-${tone}`
}

const OUTCOME_META: Readonly<Record<ResultOutcome, { label: string, tone: Tone, icon: IconName }>> = {
  submitted: { label: 'Submitted', tone: 'green', icon: 'check' },
  updated: { label: 'Updated', tone: 'green', icon: 'check' },
  cancelled: { label: 'Cancelled', tone: 'grey', icon: 'ban' },
  failed: { label: 'Submission failed', tone: 'red', icon: 'alert' },
}

export function outcomeMeta(outcome: string) {
  return (OUTCOME_META as Record<string, (typeof OUTCOME_META)[ResultOutcome] | undefined>)[outcome]
    ?? { label: 'Done', tone: 'grey' as Tone, icon: 'check' as IconName }
}

const CARD_STATE_META: Readonly<Record<Exclude<CardState, 'open'>, { label: string, tone: Tone, icon: IconName }>> = {
  used: { label: 'Confirmed', tone: 'green', icon: 'check' },
  superseded: { label: 'Replaced by a newer card', tone: 'grey', icon: 'ban' },
  discarded: { label: 'Discarded', tone: 'grey', icon: 'x' },
}

export function cardStateMeta(state: string) {
  return (CARD_STATE_META as Record<string, (typeof CARD_STATE_META)[keyof typeof CARD_STATE_META] | undefined>)[state]
    ?? { label: 'Closed', tone: 'grey' as Tone, icon: 'ban' as IconName }
}

/** Text of the loading state while a card action runs (the required "API loading state"). */
export function cardBusyLabel(action: CardAction, decision: 'confirm' | 'discard'): string {
  if (decision === 'discard') return 'Discarding...'
  return action === 'cancel' ? 'Cancelling request...' : 'Submitting to ReqRes...'
}

/* ---- Time ---- */

const MINUTE = 60_000
const HOUR = 60 * MINUTE
const DAY = 24 * HOUR

/** "just now", "5 min ago", "3 h ago", "yesterday", "4 d ago", then the ISO date. Bad input gives "". */
export function relativeTime(iso: string, now: number = Date.now()): string {
  const then = Date.parse(iso)
  if (Number.isNaN(then)) return ''
  const diff = now - then
  if (diff < MINUTE) return 'just now' // includes small clock skew into the future
  if (diff < HOUR) return `${Math.floor(diff / MINUTE)} min ago`
  if (diff < DAY) return `${Math.floor(diff / HOUR)} h ago`
  if (diff < 2 * DAY) return 'yesterday'
  if (diff < 7 * DAY) return `${Math.floor(diff / DAY)} d ago`
  return new Date(then).toISOString().slice(0, 10)
}

/** Clock time of a message, e.g. "11:05". `timeZone` is only passed by tests. */
export function formatClock(iso: string, timeZone?: string): string {
  const date = new Date(iso)
  if (Number.isNaN(date.getTime())) return ''
  return date.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone })
}

/** Date and time for cards, e.g. "25 Sep 2026, 11:05". */
export function formatDateTime(iso: string | null | undefined, timeZone?: string): string {
  if (!iso) return ''
  const date = new Date(iso)
  if (Number.isNaN(date.getTime())) return ''
  return date.toLocaleString('en-GB', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
    timeZone,
  })
}

/** "640 ms" or "1.2 s". */
export function formatDuration(ms: number): string {
  if (!Number.isFinite(ms) || ms < 0) return ''
  if (ms < 1000) return `${Math.round(ms)} ms`
  return `${(ms / 1000).toFixed(1)} s`
}

/* ---- Card fields ---- */

/** Value to show for a card field; blank values become an en dash. */
export function fieldValue(value: string | null | undefined): string {
  const text = (value ?? '').trim()
  return text || '–'
}

/** True when a field carries a real change (an old value that differs from the new one). */
export function fieldHasDiff(field: CardField): boolean {
  return field.old_value !== null && field.old_value !== undefined && field.old_value !== field.value
}

/* ---- Conversations ---- */

export function sortConversations(list: readonly ConversationSummary[]): ConversationSummary[] {
  return [...list].sort((a, b) => Date.parse(b.updated_at) - Date.parse(a.updated_at) || b.id - a.id)
}

/** Inserts or replaces a summary and keeps the list newest-first. */
export function upsertConversation(list: readonly ConversationSummary[], summary: ConversationSummary): ConversationSummary[] {
  return sortConversations([...list.filter(c => c.id !== summary.id), summary])
}

export interface ConversationBadge {
  kind: 'card' | 'form'
  label: string
}

/** Badges for the sidebar: an open card and/or the form type being filled. */
export function conversationBadges(summary: ConversationSummary): ConversationBadge[] {
  const badges: ConversationBadge[] = []
  if (summary.has_pending_card) badges.push({ kind: 'card', label: 'Awaiting confirmation' })
  if (summary.active_request_type) {
    badges.push({ kind: 'form', label: summary.active_request_type === 'leave' ? 'Leave form' : 'Claim form' })
  }
  return badges
}

/** A conversation the user has not typed into yet (safe to reuse instead of creating another). */
export function isEmptyConversation(summary: ConversationSummary | undefined, messages: readonly Message[]): boolean {
  return !!summary && messages.length === 0 && !summary.has_pending_card && !summary.active_request_type
}

/* ---- Messages ---- */

function byTime(a: Message, b: Message): number {
  return Date.parse(a.created_at) - Date.parse(b.created_at) || a.id - b.id
}

/** Merges messages by id (incoming wins) and orders them oldest-first. Optimistic (negative-id) messages stay last on ties. */
export function mergeMessages(existing: readonly Message[], incoming: readonly Message[]): Message[] {
  const byId = new Map<number, Message>()
  for (const message of [...existing, ...incoming]) byId.set(message.id, message)
  return [...byId.values()].sort(byTime)
}

/** Placeholder for the user's message while the request is in flight (negative id = not yet saved). */
export function optimisticMessage(tempId: number, content: string, now: Date = new Date(), attachments: AttachmentInfo[] = []): Message {
  return { id: tempId, sender_type: 'user', content, created_at: now.toISOString(), ui: null, trace: null, attachments }
}

export function isOptimistic(message: Message): boolean {
  return message.id < 0
}

/** Applies a TurnResponse: drops the optimistic message, merges the saved ones (user message first). */
export function applyTurn(messages: readonly Message[], tempId: number | null, turn: TurnResponse): Message[] {
  const kept = tempId === null ? messages : messages.filter(m => m.id !== tempId)
  const incoming = [...(turn.user_message ? [turn.user_message] : []), ...turn.assistant_messages]
  return mergeMessages(kept, incoming)
}

function isOpenCard(message: Message): boolean {
  return message.ui?.type === 'confirmation_card' && message.ui.state === 'open'
}

function withCardState(message: Message, state: CardState): Message {
  if (message.ui?.type !== 'confirmation_card') return message
  const ui: ConfirmationCardData = { ...message.ui, state }
  return { ...message, ui }
}

/**
 * Keeps card states consistent with the contract: only the newest confirmation card can be open, and no card
 * is open when the conversation has no pending card. `acted` records the decision the user just took.
 */
export function reconcileCards(
  messages: readonly Message[],
  opts: { hasPendingCard: boolean, acted?: { cardId: string, state: CardState } },
): Message[] {
  let next = messages.map(m =>
    opts.acted && m.ui?.type === 'confirmation_card' && m.ui.card_id === opts.acted.cardId
      ? withCardState(m, opts.acted.state)
      : m,
  )
  const openIndexes = next.flatMap((m, i) => (isOpenCard(m) ? [i] : []))
  const last = openIndexes[openIndexes.length - 1]
  next = next.map((m, i) => {
    if (!isOpenCard(m)) return m
    return i === last && opts.hasPendingCard ? m : withCardState(m, 'superseded')
  })
  return next
}

/** True when the newest message is one the user has not seen the answer to (used to decide auto-scroll). */
export function lastMessageIsUser(messages: readonly Message[]): boolean {
  return messages[messages.length - 1]?.sender_type === 'user'
}

/** Text spoken by the aria-live region for a new assistant message. */
export function announcementFor(message: Message): string {
  const parts = [message.content.trim()]
  if (message.ui?.type === 'confirmation_card' && message.ui.state === 'open') {
    parts.push(`${message.ui.title}. Use the ${message.ui.confirm_label} button or Discard.`)
  }
  else if (message.ui?.type === 'status_card') {
    parts.push(message.ui.requests.length ? `${message.ui.requests.length} request(s) listed.` : 'No matching requests.')
  }
  else if (message.ui?.type === 'result_card') {
    parts.push(message.ui.message)
  }
  else if (message.ui?.type === 'balance_card') {
    parts.push(`Leave balance for ${message.ui.year}: ${message.ui.lines.length} leave type(s) shown.`)
  }
  return parts.filter(Boolean).join(' ')
}

/* ---- Composer ---- */

/** True when the trimmed text is 1..1000 characters (the backend counts the trimmed text) and no turn is in flight. */
export function canSend(text: string, busy: boolean): boolean {
  const length = text.trim().length
  return !busy && length > 0 && length <= MAX_MESSAGE_LENGTH
}

/** Characters left, counting the trimmed text like the backend does (negative = over the limit). */
export function remainingChars(text: string): number {
  return MAX_MESSAGE_LENGTH - text.trim().length
}

/** True when the scroll position is within `threshold` px of the bottom (so auto-scroll may follow new messages). */
export function isNearBottom(metrics: { scrollTop: number, scrollHeight: number, clientHeight: number }, threshold = 80): boolean {
  return metrics.scrollHeight - metrics.scrollTop - metrics.clientHeight <= threshold
}

/* ---- Errors ---- */

export type ChatAction = 'load' | 'send' | 'card'

/** User-facing message for a chat API failure (never echoes server text). `status` undefined = network error. */
export function chatErrorMessage(status: number | undefined, action: ChatAction): string {
  if (status === undefined) return 'Cannot reach the server. Check your connection and try again.'
  if (status === 403) return 'The chat is available to employees only.'
  if (status === 404) return 'That conversation could not be found.'
  if (status === 409) return 'That card is out of date.'
  if (status === 422) return action === 'send' ? 'That message could not be sent. Keep it between 1 and 1000 characters.' : 'That request was not accepted.'
  if (status === 429) return 'Too many requests. Please wait a moment and try again.'
  if (status >= 500) return 'The server had a problem. Please try again in a moment.'
  return 'Something went wrong. Please try again.'
}

const WARNING_MESSAGES: Readonly<Record<WarningCode, string>> = {
  llm_unavailable: 'The AI service is unavailable, please try again.',
  llm_invalid_output: 'The AI gave an answer I could not use. Please rephrase and try again.',
  submission_failed: 'The submission to ReqRes failed. Your request is saved; use Retry on the card to try again.',
  stale_card: 'That card is out of date.',
}

/** Banner text for a `warning_code`; null when there is nothing to show (or an unknown code). */
export function warningMessage(code: string | null | undefined): string | null {
  if (!code) return null
  return (WARNING_MESSAGES as Record<string, string | undefined>)[code] ?? 'Something needs your attention. Please try again.'
}
<script setup lang="ts">
import type { Message } from '~/types/chat'

const props = defineProps<{
  conversationId: number | null
  messages: Message[]
  loading: boolean
  sending: boolean
  acting: { cardId: string, decision: 'confirm' | 'discard' } | null
  busy: boolean
}>()
const emit = defineEmits<{
  action: [cardId: string, decision: 'confirm' | 'discard']
  suggest: [text: string]
}>()

const scroller = ref<HTMLElement | null>(null)
/** True while the view follows new messages; turns false as soon as the user scrolls up. */
const following = ref(true)
const announcement = ref('')

// Instant (not smooth) on purpose: a smooth scroll fires scroll events that would look like the user scrolling up.
function scrollToBottom() {
  const el = scroller.value
  if (el) el.scrollTop = el.scrollHeight
}

function onScroll() {
  const el = scroller.value
  if (el) following.value = isNearBottom(el)
}

function jumpToLatest() {
  following.value = true
  scrollToBottom()
}

// A different conversation: start at the bottom and stay silent (only NEW assistant messages are announced).
watch(() => props.conversationId, () => {
  following.value = true
  announcement.value = ''
})

// Messages that are on screen when a conversation finishes loading are not "new".
let announcedUpTo = 0
watch(() => props.loading, (loading) => {
  if (!loading) announcedUpTo = props.messages.reduce((max, m) => Math.max(max, m.id), 0)
}, { immediate: true })

watch(() => props.messages, async (list, previous) => {
  if (props.loading) return
  const fresh = list.filter(m => m.sender_type === 'assistant' && m.id > announcedUpTo)
  if (fresh.length && previous.length) {
    announcement.value = fresh.map(announcementFor).join(' ')
  }
  announcedUpTo = Math.max(announcedUpTo, ...list.map(m => m.id))
  // Own message: always show it. Otherwise only follow when the user has not scrolled up.
  if (lastMessageIsUser(list)) following.value = true
  await nextTick()
  if (following.value) scrollToBottom()
})

watch(() => [props.loading, props.sending, props.acting], async () => {
  await nextTick()
  if (following.value) scrollToBottom()
})

const isEmpty = computed(() => !props.loading && props.messages.length === 0)
</script>

