export function activeInboxCardId(messages: readonly Message[]): string | null {
  for (let i = messages.length - 1; i >= 0; i--) {
    const card = inboxCardOf(messages[i]!)
    if (card && card.state === 'open') return card.card_id
  }
  return null
}

