export function inboxCardAnnouncement(card: Pick<InboxCardData, 'position' | 'title' | 'kind' | 'state'>): string {
  const head = `${positionLabel(card.position)}. ${card.title}.`
  if (card.state !== 'open') return head
  return card.kind === 'approval' ? `${head} Choose Approve, Reject or Skip.` : `${head} Choose Got it or Skip.`
}
